+static unsigned
+dissect_gsm_old_T_globalValue(bool implicit_tag _U_, tvbuff_t *tvb _U_, unsigned offset _U_, asn1_ctx_t *actx _U_, proto_tree *tree _U_, int hf_index _U_) {
+  tvbuff_t *oid_tvb = NULL;
+  const char *opcode_string;
+
+  offset = dissect_ber_object_identifier(implicit_tag, actx, tree, tvb, offset, hf_index, &oid_tvb);
+
+  /* OPERATION ::= CHOICE { localValue INTEGER, globalValue OBJECT IDENTIFIER }
+   * is standard per ITU-T X.219 / TCAPv2 (ETSI TS 129.002, TCAPv2Messages.asn). */
+  if (oid_tvb != NULL && tvb_reported_length(oid_tvb) == 1) {
+    opcode = tvb_get_uint8(oid_tvb, 0);
+    opcode_string = gsm_map_opr_code(opcode, actx->created_item);
+    col_append_str(actx->pinfo->cinfo, COL_INFO, opcode_string);
+    col_append_str(actx->pinfo->cinfo, COL_INFO, " ");
+    /* Rewrite the item label to mirror the localValue display
+     * opcode_string instead of the raw OID. */
+    proto_item_set_text(actx->created_item, "globalValue: %s (%u)",
+        opcode_string, opcode);
+  }
+  return offset;
+}
+
+
+static unsigned
+dissect_gsm_old_T_errorGlobalValue(bool implicit_tag _U_, tvbuff_t *tvb _U_, unsigned offset _U_, asn1_ctx_t *actx _U_, proto_tree *tree _U_, int hf_index _U_) {
+  tvbuff_t *oid_tvb = NULL;
+
+  /* ERROR ::= CHOICE { localValue INTEGER, globalValue OBJECT IDENTIFIER } -
+   * mirror of MAP-OPERATION/globalValue for error codes carried in the same
+   * compact one-octet-OID encoding. */
+  offset = dissect_ber_object_identifier(implicit_tag, actx, tree, tvb, offset, hf_index, &oid_tvb);
+
+  if (oid_tvb != NULL && tvb_reported_length(oid_tvb) == 1) {
+    errorCode = tvb_get_uint8(oid_tvb, 0);
+  }
+  return offset;
+}
